import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Vector2 } from 'three/webgpu';
import { texture, uniform, uv, positionLocal, normalLocal, Fn, vec2, sub, mul } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // --- Load assets ---
  const imageTexture = ctx.textureLoader.load(config.visual.imageUrl);
  const depthTexture = ctx.textureLoader.load(config.visual.depthMapUrl);
  imageTexture.anisotropy = 8;
  depthTexture.anisotropy = 8;

  // --- Geometry ---
  const aspect = 512 / 320; // atlas source rect ratio
  const width = 2.5;
  const height = width / aspect;
  const geometry = new PlaneGeometry(width, height, 64, 64);

  // --- TSL displacement material ---
  const mouseUniform = uniform(new Vector2(0.5, 0.5));
  const colorNode = texture(imageTexture);
  const depthNode = texture(depthTexture);

  const vertexModifier = Fn(() => {
    const h = depthNode.sample(uv()).r;
    const offset = sub(mouseUniform, vec2(0.5)).mul(0.2).mul(h);
    positionLocal.addAssign(normalLocal.mul(offset));
  })();

  const material = new MeshBasicNodeMaterial({
    colorNode,
    vertexNode: vertexModifier,
  });

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  const pos = config.scenePlacement.position;
  mesh.position.set(pos.x, pos.y, pos.z);
  mesh.rotation.set(config.scenePlacement.rotation.x, config.scenePlacement.rotation.y, config.scenePlacement.rotation.z);
  mesh.scale.set(config.scenePlacement.scale.x, config.scenePlacement.scale.y, config.scenePlacement.scale.z);

  // Store initial Y for hover lift
  mesh.userData.originalY = pos.y;

  // --- Interaction handlers ---
  mesh.userData.handlers = {
    pointerover: () => {
      gsap.to(mesh.position, {
        y: mesh.userData.originalY + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    pointerout: () => {
      gsap.to(mesh.position, {
        y: mesh.userData.originalY,
        duration: 0.5,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    click: () => {
      // Emit event as specified
      if (ctx.events && ctx.events.emit) {
        ctx.events.emit('hub-features.select');
      }
      // Data binding: navigate via checkout URL (itemId not given, skip)
    },
    pointermove: (event) => {
      // Update mouse uniform for parallax
      mouseUniform.value.set(
        event.clientX / window.innerWidth,
        event.clientY / window.innerHeight
      );
    },
  };

  // --- Cleanup ---
  mesh.userData.cleanup = () => {
    gsap.killTweensOf(mesh.position);
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
    depthTexture.dispose();
  };

  return mesh;
}
